insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('lt-07', 'l-tarqeem', 3, '«زار المعلم معرض الكتاب فاشترى كتباً في النحو، والبلاغة، والأدب» — الفواصل هنا استخدمت لـ:', '["الفصل بين جمل تامة","الفصل بين المعطوفات وأنواع الشيء","الدلالة على حذف كلام","حصر جملة اعتراضية"]'::jsonb, 1, 'من مواضع الفاصلة الفصل بين المعطوفات المتشابهة وأقسام الشيء.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
