insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('lr-01', 'l-reading', 1, 'أي العبارات الآتية تُعد حقيقة لا رأياً؟', '["الرياضيات أجمل المواد الدراسية","يتكون الماء من الأكسجين والهيدروجين","القراءة أمتع هواية","ينبغي أن تبدأ الدراسة مبكراً"]'::jsonb, 1, 'الحقيقة قابلة للتحقق العلمي ولا تختلف باختلاف الأشخاص. أما «أجمل» و«أمتع» و«ينبغي» فدلائل رأي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
