insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('lv-07', 'l-vocab', 2, 'مصدر الفعل «استعملَ»:', '["معمل","استعمال","عمالة","إعمال"]'::jsonb, 1, 'مصدر السداسي استفعل: استفعال — استعمل → استعمال، وهمزته وصل.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('lv-08', 'l-vocab', 2, 'مصدر الفعل «أبدعَ»:', '["بدعة","إبداع","ابتداع","بديع"]'::jsonb, 1, 'مصدر الرباعي أفعل: إفعال — أبدع → إبداع، وهمزته قطع مكسورة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('lv-09', 'l-vocab', 3, '«صعد الطلاب إلى أعلى الطابق العلوي فوق» — العيب الأسلوبي في الجملة:', '["خطأ إملائي","الحشو والتكرار بلا فائدة","خطأ في الترقيم","غموض المعنى"]'::jsonb, 1, 'اجتمع «أعلى» و«العلوي» و«فوق» بمعنى واحد، والإيجاز يقتضي حذف الزائد: صعد الطلاب إلى الطابق العلوي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('lv-10', 'l-vocab', 2, 'ضد كلمة «الإيجاز»:', '["الاختصار","الإطناب","البلاغة","الوضوح"]'::jsonb, 1, 'الإيجاز التعبير بأقل الألفاظ، وضده الإطناب (الإطالة والتوسع).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('lv-11', 'l-vocab', 2, 'معنى كلمة «يحتذي» في جملة «يحتذي المعلمُ النماذجَ التربوية الناجحة»:', '["ينتقد","يقتدي ويتبع","يبتعد","يتجاهل"]'::jsonb, 1, 'يحتذي أي يقتدي به ويسير على منواله، ومنه «يحتذى به».') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('lv-12', 'l-vocab', 3, 'الاستفهام في قوله تعالى: ﴿هل جزاء الإحسان إلا الإحسان﴾ خرج إلى غرض بلاغي هو:', '["طلب المعرفة","التقرير","السخرية","التعجيز"]'::jsonb, 1, 'الاستفهام هنا لا يطلب جواباً بل يقرر حقيقة أن جزاء الإحسان إحسان.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('lv-13', 'l-vocab', 2, 'جمع كلمة «صحيفة»:', '["صحائف وصحف","صواحف","صحيفات فقط","أصحفة"]'::jsonb, 0, 'تجمع صحيفة على صحف وصحائف.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('lv-14', 'l-vocab', 2, 'أي العبارات الآتية أسلوب إنشائي؟', '["حضر المعلم مبكراً","الاختبار سهل","اجتهدْ في دروسك","نجح الطلاب جميعاً"]'::jsonb, 2, '«اجتهدْ» أسلوب أمر، والأمر من الأساليب الإنشائية الطلبية التي لا تحتمل الصدق والكذب.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-21', 't-theories', 2, 'لاحظ معلم أن طالباً يحل مسائل الضرب بإتقان في الرياضيات، لكنه يعجز عن تطبيقها في حساب تكلفة مشترياته في الحياة. المفهوم التربوي الذي يعالج هذه الفجوة:', '["انتقال أثر التعلم","الاستعداد للتعلم","النضج العقلي","التغذية الراجعة"]'::jsonb, 0, 'انتقال أثر التعلم هو توظيف ما تعلمه الطالب في مواقف جديدة؛ وضعفه يعالج بتنويع سياقات التطبيق وربط التعلم بالحياة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-22', 't-theories', 3, 'وضع معلم مسألة أمام طلابه فحدّقوا فيها طويلاً ثم انبثق الحل فجأة لدى أحدهم دون محاولات تدريجية. هذا التعلم يفسَّر بنظرية:', '["المحاولة والخطأ عند ثورندايك","الاستبصار (الجشطلت)","الإشراط الإجرائي","التعلم المبرمج"]'::jsonb, 1, 'الجشطلت ترى التعلم إدراكاً مفاجئاً للعلاقات في الموقف ككل (الاستبصار)، بخلاف المحاولة والخطأ التدريجية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-23', 't-theories', 2, 'من مبادئ نظرية الجشطلت في التعلم:', '["الكل أكبر من مجموع أجزائه وإدراك الموقف كوحدة","التعلم سلسلة ارتباطات آلية بين مثير واستجابة","التعزيز شرط لكل تعلم","التعلم لا يحدث إلا بالتكرار"]'::jsonb, 0, 'الجشطلت تركز على إدراك البنية الكلية والعلاقات بين الأجزاء، لا على تجزئة الموقف إلى ارتباطات منفصلة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-24', 't-theories', 2, 'يوزّع معلم مراجعة المقرر على فترات متباعدة خلال الفصل بدل حشرها في ليلة الاختبار. المبدأ الذي يستند إليه:', '["التعلم الموزع أبقى أثراً من المكثف","الحفظ الآلي أفضل من الفهم","التعلم الكلي أفضل دائماً","المراجعة لا تؤثر في الاحتفاظ"]'::jsonb, 0, 'التعلم الموزع على فترات يقاوم النسيان أكثر من التعلم المكثف المتراكم، وهو من أثبت مبادئ سيكولوجية التعلم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-25', 't-theories', 3, 'طالب يحفظ تعريفاً دون أن يربطه بأي معنى أو خبرة سابقة. وفق أوزوبل هذا يسمى:', '["تعلماً ذا معنى","تعلماً استقبالياً ذا معنى","تعلماً صماً (آلياً)","تعلماً بالاكتشاف"]'::jsonb, 2, 'التعلم الصمّ حفظ دون ربط بالبنية المعرفية، وأوزوبل يقابله بالتعلم ذي المعنى القائم على الربط بالمعرفة السابقة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
